// Arma la respuesta con el contrato que espera el frontend: { respuesta, productos }.
// El agente deja el texto final en $json.output.
const salida = $json && $json.output ? String($json.output).trim()
  : 'No encontré una respuesta para eso. ¿Me cuentas qué repuesto buscas y para qué vehículo (marca, modelo y año)?';

return {
  json: {
    respuesta: salida,
    productos: []
  }
};
